MODEL (
  name silver.order_item,
  kind INCREMENTAL_BY_TIME_RANGE (time_column order_date),
  grain (order_id, line_no),
  partitioned_by (days(order_date)),
  audits (order_item_key_unique, not_null(columns := (order_date)))
);

SELECT
  CAST(index AS BIGINT) AS line_no,
  CONVERT_TIMEZONE(
    'Europe/Paris',
    'UTC',
    CAST(CASE
      WHEN (
        SUBSTRING(CAST(created_at AS VARCHAR), 11) LIKE '%+%'
        OR SUBSTRING(CAST(created_at AS VARCHAR), 11) LIKE '%-%'
      )
      OR UPPER(SUBSTRING(CAST(created_at AS VARCHAR), 11)) LIKE '%Z%'
      THEN NULL
      ELSE REPLACE(REPLACE(CAST(created_at AS VARCHAR), 'T', ' '), 't', ' ')
    END AS TIMESTAMPNTZ)
  ) AS order_date,
  CAST(order_id AS VARCHAR) AS order_id,
  CAST(qty AS BIGINT) AS quantity,
  CAST(CAST(CAST(total AS DECIMAL(12, 4)) AS DECIMAL(38, 9)) / CAST(qty AS BIGINT) AS DECIMAL(12, 4)) AS unit_price,
  CAST(ARRAY_CONSTRUCT() AS ARRAY) AS _quality_flags,
  TRUE AS _quality_ok
FROM bronze.shopify__order_lines
